css:
@media print { @page { size: 80mm auto; margin: 2mm; } }
.pl { width: 76mm; font-family: Arial, Helvetica, "Liberation Sans", sans-serif; color: #000; }
.print-format td, .print-format th { padding: 1px !important; color: #000 !important; border: none !important; }
.pl .hr-bold { border: 0; border-top: 1px solid #000; margin: 2px 0; }
.pl .center-text { text-align: center; }
.pl table { width: 100%; }

html:
{#- Draft PICK LIST — AMANK layout (SNO/ITEM/CODE/RACK/QTY/MRP grouped by
    brand), dimensions/spacing tuned for the 80mm thermal printer. -#}
{% set address = None %}
{% if doc.customer_address %}{% set address = frappe.get_doc("Address", doc.customer_address) %}{% endif %}
{% set item_racks = get_item_racks(doc.items) %}
{% set show_rack = item_racks | length > 0 %}
{% set cust = doc.customer_name or doc.customer or "Walk-in Customer" %}
{% set stamp = frappe.utils.format_datetime(doc.creation, "dd-MM-yyyy HH:mm:ss") if doc.creation else frappe.utils.format_datetime(frappe.utils.now(), "dd-MM-yyyy HH:mm:ss") %}

<div class="pl">

<table border="0" cellpadding="1" cellspacing="0" style="font-size:8px; width:100%; word-wrap:break-word;">
    <tr>
        <td width="58%" style="vertical-align:top;">
            <b style="font-size:11px;">{{ cust }}</b>
            <div style="font-size:8px; margin:1px 0 0 0;">
                {{ doc.address_display or "" }}
                {% if address and address.get("gstin") %}GSTIN: {{ address.get("gstin") }}
                {% elif doc.tax_id %}GSTIN: {{ doc.tax_id }}{% endif %}
            </div>
        </td>
        <td width="42%" style="text-align:right; vertical-align:top;">
            <b style="font-size:9px;">Pick No:&nbsp;{{ doc.name }}</b><br>
            <b style="font-size:9px;">Date :&nbsp;{{ frappe.utils.format_date(doc.posting_date) if doc.posting_date else frappe.utils.format_date(frappe.utils.today()) }}</b>
        </td>
    </tr>
</table>

<hr class="hr-bold">

<div class="center-text" style="margin:3px 0;">
    {% if doc.docstatus == 1 %}<div style="font-size:10px; font-weight:bold;">SUBMITTED</div>
    {% elif doc.docstatus == 2 %}<div style="font-size:10px; font-weight:bold;">CANCELLED</div>
    {% else %}<div style="font-size:9px; font-weight:bold;">DRAFT - {{ cust }} - {{ stamp }}</div>{% endif %}
</div>

<hr class="hr-bold">

<table border="0" cellpadding="1" cellspacing="0" style="font-size:8px; width:100%; table-layout:fixed; word-wrap:break-word; overflow-wrap:break-word;">
    <thead>
        <tr style="border-bottom:1px solid #999;">
            <th style="text-align:left; font-size:8px;" width="{{ '8%' if show_rack else '10%' }}"><b>SNO.</b></th>
            <th style="text-align:left; font-size:8px;" width="{{ '32%' if show_rack else '35%' }}"><b>ITEM NAME</b></th>
            <th style="text-align:left; font-size:8px;" width="{{ '18%' if show_rack else '20%' }}"><b>CODE</b></th>
            {% if show_rack %}<th style="text-align:left; font-size:8px;" width="14%"><b>RACK</b></th>{% endif %}
            <th style="text-align:left; font-size:8px;" width="{{ '12%' if show_rack else '15%' }}"><b>QTY</b></th>
            <th style="text-align:right; font-size:8px;" width="{{ '16%' if show_rack else '20%' }}"><b>M.R.P</b></th>
        </tr>
    </thead>
    <tbody style="font-size:8px;">
        {% set grouped_items = {} %}
        {% for item in doc.items|sort(attribute='item_name') %}
            {% set parent_brand = item.brand or "" %}
            {% if parent_brand not in grouped_items %}{% set _ = grouped_items.update({parent_brand: []}) %}{% endif %}
            {% set _ = grouped_items[parent_brand].append(item) %}
        {% endfor %}
        {% set serial_number = {'count': 0} %}
        {% for parent_brand, items in grouped_items|dictsort %}
            {% if parent_brand %}
            <tr><td colspan="{{ 6 if show_rack else 5 }}" style="text-align:left; font-size:8px; {% if not loop.first %}border-top:1px solid #ccc;{% endif %}"><b>{{ parent_brand }}</b></td></tr>
            {% endif %}
            {% for item in items %}
                {% set _ = serial_number.update({'count': serial_number.count + 1}) %}
                <tr>
                    <td style="text-align:left;">{{ serial_number.count }}</td>
                    <td style="text-align:left;">{{ item.item_name }}</td>
                    <td style="text-align:left;">{{ item.item_code }}</td>
                    {% if show_rack %}<td style="text-align:left;">{{ item_racks.get(item.item_code) or "" }}</td>{% endif %}
                    <td style="text-align:left;">{{ item.qty if item.qty % 1 else item.qty | int }}</td>
                    <td style="text-align:right;">{{ item.price_list_rate or "" }}</td>
                </tr>
            {% endfor %}
        {% endfor %}
    </tbody>
</table>

<hr class="hr-bold">
</div>
